package pe.com.dentalamericana.admin;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.com.dentalamericana.admin.dto.AdminDtos.*;import pe.com.dentalamericana.security.AuthenticatedUser;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.List;
@RestController@RequestMapping("/api/v1/admin")public class AdministrationController{private final AdministrationService service;public AdministrationController(AdministrationService service){this.service=service;}@GetMapping("/settings")@PreAuthorize("hasAuthority('USUARIO_LEER')")public List<SettingResponse>settings(){return service.settings();}@PutMapping("/settings/{key}")@PreAuthorize("hasAuthority('AJUSTE_ESCRIBIR')")public SettingResponse update(@PathVariable String key,@Valid@RequestBody UpdateSettingRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.update(key,r,a,h);}@GetMapping("/audit")@PreAuthorize("hasAuthority('AUDITORIA_LEER')")public Page<AuditResponse>audit(@RequestParam Instant from,@RequestParam Instant to,@RequestParam(required=false)String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size){return service.audits(from,to,q,page,size);}@GetMapping("/summary")@PreAuthorize("hasAnyAuthority('FINANZA_LEER','AUDITORIA_LEER')")public OperationalSummary summary(@RequestParam Instant from,@RequestParam Instant to){return service.summary(from,to);}@GetMapping("/reports/operational.csv")@PreAuthorize("hasAuthority('FINANZA_LEER')")public ResponseEntity<byte[]>csv(@RequestParam Instant from,@RequestParam Instant to){byte[]data=service.csv(from,to).getBytes(StandardCharsets.UTF_8);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=Reporte_Dental_Americana.csv").contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).body(data);}}
